import {startBreakout,stepBreakout,validBreakout} from './breakout.mjs';
export const ARCADE_START={id:'arcade-start',name:'Melanies Retro-Spiele',region:'arcadeshop',x:2,z:1.8,range:1.7,arcade:true};
export const MELANIE={id:'melanie',name:'Mit Melanie sprechen',x:-2,z:-.4,range:1.7,melanie:true};
export const ARCADE_GAMES={snake:{name:'Alpen-Snake',goal:'12 Beeren sammeln'},pong:{name:'Pong',goal:'Zuerst 5 Punkte erreichen'},breakout:{name:'Alpen-Breakout',goal:'Alle 32 Steine mit drei Bällen abräumen'}};
export const ARCADE_LEVELS={easy:{name:'Gemütlich',q:.75},normal:{name:'Klassisch',q:1},hard:{name:'Knifflig',q:1.3}};
const directions={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
export const freshArcade=()=>({best:{},runs:{},wins:{},lampAwarded:false,lampPending:false,active:null});
export function atArcade(s){return s.position.region==='arcadeshop'&&!s.position.inside&&!s.jass.active&&!s.ski.active&&!s.targets.active&&!s.climbing.checkpoint&&Math.hypot(s.position.x-ARCADE_START.x,s.position.z-ARCADE_START.z)<2.4;}
function nextRandom(c){c.rng=(Math.imul(c.rng,1664525)+1013904223)>>>0;return c.rng/4294967296;}
function food(c){const cells=[];for(let y=0;y<18;y++)for(let x=0;x<24;x++)if(!c.snake.some(p=>p[0]===x&&p[1]===y))cells.push([x,y]);return cells[Math.floor(nextRandom(c)*cells.length)];}
function serve(c,direction){const q=ARCADE_LEVELS[c.level].q;c.ball={x:240,y:160,vx:direction*185*q,vy:(nextRandom(c)-.5)*210*q};c.wait=.8;}
export function startArcade(s,kind,level,seed=Math.floor(Math.random()*4294967296)){if(!Object.hasOwn(ARCADE_GAMES,kind)||!Object.hasOwn(ARCADE_LEVELS,level)||!atArcade(s)||s.arcade.active)return{ok:false,message:'Gehe zuerst zum Automaten in Melanies Laden.'};const c={kind,level,rng:seed>>>0,time:0,countdown:3,done:false,won:false};if(kind==='snake'){Object.assign(c,{snake:[[7,9],[6,9],[5,9]],direction:'right',queue:[],acc:0,eaten:0});c.food=food(c);}else if(kind==='breakout'){startBreakout(c,ARCADE_LEVELS[level].q);}else{Object.assign(c,{paddle:160,opponent:160,points:0,against:0,wait:0});serve(c,1);}s.arcade.active=c;return{ok:true};}
export function arcadeInput(c,key){if(!c||c.done)return false;if(c.kind!=='snake')return false;const next=directions[key],prior=directions[c.queue.at(-1)||c.direction];if(!Object.hasOwn(directions,key)||!next||c.queue.length>=2||next[0]===-prior[0]&&next[1]===-prior[1]||next[0]===prior[0]&&next[1]===prior[1])return false;c.queue.push(key);return true;}
export function stepArcade(c,dt,input=0){if(!c||c.done||!Number.isFinite(dt)||dt<0||dt>.1||!Number.isFinite(input))return null;if(c.countdown>0){c.countdown=Math.max(0,c.countdown-dt);return null;}c.time=Math.min(120,c.time+dt);const q=ARCADE_LEVELS[c.level].q;let event=null;
 if(c.kind==='snake'){c.acc+=dt;const interval=.23/q;while(c.acc>=interval&&!c.done){c.acc-=interval;if(c.queue.length)c.direction=c.queue.shift();const d=directions[c.direction],head=[c.snake[0][0]+d[0],c.snake[0][1]+d[1]],eat=head[0]===c.food[0]&&head[1]===c.food[1],body=eat?c.snake:c.snake.slice(0,-1);if(head[0]<0||head[0]>=24||head[1]<0||head[1]>=18||body.some(p=>p[0]===head[0]&&p[1]===head[1])){c.done=true;break;}c.snake.unshift(head);if(eat){c.eaten++;event='food';if(c.eaten>=12){c.done=true;c.won=true;}else c.food=food(c);}else c.snake.pop();}}
 else if(c.kind==='breakout'){event=stepBreakout(c,dt,input,q);}
 else{c.paddle=Math.max(32,Math.min(288,c.paddle+Math.max(-1,Math.min(1,input))*300*dt));const aim=c.ball.y+Math.sin(c.time*2.7)*44,move=Math.max(-1,Math.min(1,(aim-c.opponent)/12));c.opponent=Math.max(32,Math.min(288,c.opponent+move*95*q*dt));if(c.wait>0)c.wait=Math.max(0,c.wait-dt);else{const steps=Math.max(1,Math.ceil(dt/.008)),step=dt/steps;for(let i=0;i<steps;i++){const b=c.ball,oldX=b.x;b.x+=b.vx*step;b.y+=b.vy*step;if(b.y<6){b.y=12-b.y;b.vy=Math.abs(b.vy);}if(b.y>314){b.y=628-b.y;b.vy=-Math.abs(b.vy);}if(b.vx<0&&oldX>=30&&b.x<=30&&Math.abs(b.y-c.paddle)<=37){b.x=30;b.vx=Math.min(330*q,Math.abs(b.vx)*1.035);b.vy=(b.y-c.paddle)*7*q;}if(b.vx>0&&oldX<=450&&b.x>=450&&Math.abs(b.y-c.opponent)<=37){b.x=450;b.vx=-Math.min(330*q,Math.abs(b.vx)*1.035);b.vy=(b.y-c.opponent)*7*q;}if(b.x< -8||b.x>488){if(b.x>488)c.points++;else c.against++;event='point';if(c.points>=5||c.against>=5){c.done=true;c.won=c.points>=5;}else serve(c,b.x>488?-1:1);break;}}}}
 if(c.time>=120&&!c.done)c.done=true;return c.done?'finish':event;
}
export const arcadeScore=c=>c.kind==='snake'?c.eaten*10:c.kind==='breakout'?Math.max(0,c.bricks.filter(v=>!v).length*10-(3-c.lives)*20):Math.max(0,c.points*100-c.against*20);
export function finishArcade(s,exchange,{deferLamp=false}={}){const c=s.arcade.active;if(!atArcade(s)||!c?.done)return{ok:false,message:'Die Runde läuft noch.'};const a=s.arcade,key=c.kind+'-'+c.level,newPrize=c.won&&!a.lampAwarded&&!a.lampPending;const r=exchange(s,{give:newPrize&&!deferLamp?{lamp:1}:{}});if(!r.ok)return r;a.best[key]=Math.max(a.best[key]||0,arcadeScore(c));a.runs[key]=Math.min(1000000,(a.runs[key]||0)+1);if(c.won)a.wins[key]=Math.min(1000000,(a.wins[key]||0)+1);if(newPrize){a.lampPending=deferLamp;a.lampAwarded=!deferLamp;}a.active=null;return{ok:true,kind:c.kind,level:c.level,won:c.won,score:arcadeScore(c),time:c.time,lamp:newPrize&&!deferLamp,pending:newPrize&&deferLamp};}
export function claimLamp(s,exchange){if(!atArcade(s))return{ok:false,message:'Gehe zum Automaten, um die Lampe abzuholen.'};if(!s.arcade.lampPending||s.arcade.lampAwarded)return{ok:false,message:'Keine Lampe wartet auf dich.'};const r=exchange(s,{give:{lamp:1}});if(!r.ok)return r;s.arcade.lampPending=false;s.arcade.lampAwarded=true;return{ok:true,message:'Höhlenlampe eingepackt. In Felsengang und Kristallgrotte leuchtet sie automatisch, solange sie im Rucksack liegt.'};}
export function validArcade(a,s){const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),num=(x,lo,hi)=>Number.isFinite(x)&&x>=lo&&x<=hi,int=(x,lo,hi)=>Number.isSafeInteger(x)&&x>=lo&&x<=hi,keys=Object.keys(ARCADE_GAMES).flatMap(k=>Object.keys(ARCADE_LEVELS).map(l=>k+'-'+l));if(!obj(a)||typeof a.lampAwarded!=='boolean'||typeof a.lampPending!=='boolean'||a.lampPending&&a.lampAwarded||!['best','runs','wins'].every(k=>obj(a[k])&&Object.entries(a[k]).every(([key,n])=>keys.includes(key)&&int(n,0,k==='best'?500:1000000)))||!Object.entries(a.wins).every(([key,n])=>n<=(a.runs[key]||0)))return false;if((a.lampPending||a.lampAwarded)&&!Object.values(a.wins).some(n=>n>0))return false;if(a.active===null)return true;const c=a.active;if(!obj(c)||!atArcade(s)||!Object.hasOwn(ARCADE_GAMES,c.kind)||!Object.hasOwn(ARCADE_LEVELS,c.level)||!int(c.rng,0,4294967295)||!num(c.time,0,120)||!num(c.countdown,0,3)||typeof c.done!=='boolean'||typeof c.won!=='boolean'||c.won&&!c.done)return false;
 if(c.kind==='snake'){const cell=p=>Array.isArray(p)&&p.length===2&&int(p[0],0,23)&&int(p[1],0,17);if(!int(c.eaten,0,12)||!Array.isArray(c.snake)||c.snake.length!==3+c.eaten||!c.snake.every(cell)||new Set(c.snake.map(p=>p.join(','))).size!==c.snake.length||!c.snake.every((p,i)=>!i||Math.abs(p[0]-c.snake[i-1][0])+Math.abs(p[1]-c.snake[i-1][1])===1)||!cell(c.food)||c.eaten<12&&c.snake.some(p=>p[0]===c.food[0]&&p[1]===c.food[1])||!Object.hasOwn(directions,c.direction)||!Array.isArray(c.queue)||c.queue.length>2||!num(c.acc,0,.23/ARCADE_LEVELS[c.level].q+.1)||c.won!==(c.eaten===12))return false;let prior=directions[c.direction];for(const key of c.queue){const n=directions[key];if(!Object.hasOwn(directions,key)||!n||n[0]===-prior[0]&&n[1]===-prior[1])return false;prior=n;}}
 else if(c.kind==='breakout'){if(!validBreakout(c))return false;}
 else{const b=c.ball;if(!num(c.paddle,32,288)||!num(c.opponent,32,288)||!int(c.points,0,5)||!int(c.against,0,5)||!num(c.wait,0,.8)||!obj(b)||!num(b.x,-14,494)||!num(b.y,0,320)||!num(b.vx,-430,430)||!num(b.vy,-500,500)||c.won!==(c.points===5)||!c.done&&(c.points>=5||c.against>=5))return false;}return true;}
